import './App.css';
import default_face from "./default.png";
import root_face from "./sigma.jpg";
import {client, useConfig, useElementData, useElementColumns} from '@sigmacomputing/plugin';
import { useEffect } from 'react';
import { OrgChart } from 'd3-org-chart';
import * as d3 from 'd3';

// IMPORTANT: do not name a config key "id" — the plugin SDK overwrites
// config.id with the element id, which blanks the chart.
client.config.configureEditorPanel([
  { name: "source", type: "element" },
  { name: "name", type: "column", source: "source", allowMultiple: false },
  { name: "nodeId", type: "column", source: "source", allowMultiple: false },
  { name: "parentId", type: "column", source: "source", allowMultiple: false },
  { name: "positionName", type: "column", source: "source" },
  { name: "area", type: "column", source: "source" },
  { name: "imageUrl", type: "column", source: "source" },
  { name: "location", type: "column", source: "source" },
]);

function graph(data) {
  d3.selectAll('.container > *').remove();
  if (!data || !data.length) return;
  new OrgChart()
      .container('.container')
      .data(data)
      .nodeHeight((d) => 85 + 25)
      .nodeWidth((d) => 220 + 2)
      .childrenMargin(d => 50)
      .compactMarginBetween(d => 35)
      .compactMarginPair(d => 30)
      .neightbourMargin((a, b) => 20)
      .buttonContent(({ node, state }) => {
        return `<div style="border-radius:3px;padding:3px;font-size:10px;margin:auto auto;background-color:lightgray"> <span style="font-size:9px">${
            node.children
                ? `<i class="fas fa-chevron-up"></i>`
                : `<i class="fas fa-chevron-down"></i>`
        }</span> ${node.data._directSubordinates}  </div>`;
      })
      .nodeContent(function (d, i, arr, state) {
        const color = '#FFFFFF';
        const imageDiffVert = 25 + 2;
        const img = d.data.imageUrl || default_face;
        return `
                <div style='width:${d.width}px;height:${d.height}px;padding-top:${imageDiffVert - 2}px;padding-left:1px;padding-right:1px;'>
                        <div style="font-family: 'Inter', sans-serif;background-color:${color};margin-left:-1px;width:${d.width - 2}px;height:${d.height - imageDiffVert}px;border-radius:10px;border: 1px solid #E4E2E9;display:flex;justify-content:center;align-items:center;flex-direction:column;position:relative">
                            <img src="${img}" style="margin-left:-139px;border-radius:500px;width:50px;height:50px;position:absolute;top:-10px;" />
                            <div style="font-size:15px;color:#08011E;margin-left:-100px;margin-top:5px;position:absolute;top:35px;">${d.data.name || ''}</div>
                            <div style="color:#4346FF;font-size:10px;font-weight:bold;position:absolute;top:62px;left:12px;">${d.data.positionName || ''}</div>
                            <div style="color:#716E7B;font-size:10px;position:absolute;top:80px;left:12px;">${d.data.area || ''}</div>
                            <div style="color:#716E7B;font-size:10px;position:absolute;right:8px;bottom:8px;">${d.data.location || ''}</div>
                        </div>
                    </div>`;
      })
      .render();
}

/** Plugin SDK expects a string element id — API specs sometimes store {kind,elementId}. */
function sourceElementId(source) {
  if (!source) return null;
  if (typeof source === 'string') return source;
  if (typeof source === 'object') return source.elementId || source.id || null;
  return null;
}

function col(sigmaData, columns, key) {
  if (!key) return null;
  if (sigmaData?.[key]) return sigmaData[key];
  // Fallback: config sometimes stores column name; data is keyed by column id
  const match = Object.entries(columns || {}).find(
    ([, meta]) => meta?.name === key || meta?.columnId === key || meta?.id === key
  );
  if (match && sigmaData?.[match[0]]) return sigmaData[match[0]];
  return null;
}

function transform(config, columns, sigmaData) {
  const nameKey = config.name;
  // Prefer nodeId; tolerate legacy "id" binding if SDK didn't clobber it
  const idKey = config.nodeId || (config.id && !String(config.id).startsWith('plg') ? config.id : null);
  const parentKey = config.parentId;
  const positionName = config.positionName;
  const area = config.area;
  const imageUrl = config.imageUrl;
  const location = config.location;

  const names = col(sigmaData, columns, nameKey);
  const ids = col(sigmaData, columns, idKey);
  const parents = col(sigmaData, columns, parentKey);
  const positions = col(sigmaData, columns, positionName);
  const areas = col(sigmaData, columns, area);
  const images = col(sigmaData, columns, imageUrl);
  const locations = col(sigmaData, columns, location);

  const data = [];
  const roots = [];
  if (!names?.length || !ids?.length || !parents) {
    console.warn('orgchart: missing columns', {
      nameKey, idKey, parentKey,
      keys: Object.keys(sigmaData || {}),
      config,
    });
    return data;
  }

  for (let idx = 0; idx < names.length; ++idx) {
    const pid = parents[idx];
    data.push({
      positionName: positions?.[idx],
      area: areas?.[idx],
      imageUrl: images?.[idx] || default_face,
      location: locations?.[idx],
      name: names[idx],
      id: ids[idx],
      // d3-org-chart wants null (not undefined) for roots
      parentId: pid == null || pid === '' ? null : pid,
    });
    if (pid == null || pid === '') roots.push(idx);
  }

  if (roots.length > 1) {
    for (const idx of roots) data[idx].parentId = 'Root';
    data.push({
      positionName: '',
      area: '',
      imageUrl: root_face,
      location: '',
      name: 'Organization',
      id: 'Root',
      parentId: null,
    });
  }
  return data;
}

function App() {
  const config = useConfig();
  const elementId = sourceElementId(config.source);
  const columns = useElementColumns(elementId);
  const sigmaData = useElementData(elementId);

  useEffect(() => {
    graph(transform(config, columns, sigmaData));
  }, [config, columns, sigmaData]);

  const names = col(sigmaData, columns, config.name);
  const n = names?.length || 0;
  const dbg = !n
    ? `src=${JSON.stringify(config.source)} id=${elementId || '∅'} nameKey=${config.name || '∅'} dataKeys=[${Object.keys(sigmaData || {}).join(',')}] colKeys=[${Object.keys(columns || {}).join(',')}]`
    : '';
  return (
      <div className="App">
        {!n ? (
          <div className="empty">
            No org rows in source — select an account or check column bindings.
            <div style={{marginTop: 8, fontSize: 11, opacity: 0.7, wordBreak: 'break-all'}}>{dbg}</div>
          </div>
        ) : null}
        <div className="container"/>
      </div>
  );
};

export default App;
